/**
 * One scenario per check of compliance-calendar-build-standard, for Claim Clock.
 *
 * Generated by `npx @aipathway/conformance init compliance-calendar-build-standard`,
 * then written for an Australian head contractor with jobs in New South Wales,
 * Queensland and Victoria, receiving progress claims from its subbies.
 *
 * THE FIXTURES ARE ILLUSTRATIVE. The business-day counts follow the shape of
 * the security of payment Acts (a payment schedule within a set number of
 * business days of the claim being served, or the contract's shorter period),
 * but they exercise the build: they are not legal advice and not a statement
 * of the current law in any state. The business keeps its own rule set, with a
 * citation on each version, and a person checks it when an Act changes.
 *
 * The stub derives its own due date in calendar time (it counts a month as 30
 * days), so each fixture rule also carries a calendar ceiling for the stub of
 * the business-day span plus a week. The build's due date is the business-day
 * count under the same rule version, which is the date in every reminder.
 *
 * Every holds() reads the trace (world.calls), never the build's return value,
 * and returns a strict boolean. Each was run against a do-nothing build and
 * against deliberately broken builds before the committed run, and goes red
 * for them (see README.md).
 */

import { CalendarWorld } from "@aipathway/conformance";

const DAY = 86_400_000;
const NOW = new Date("2026-09-21T00:00:00.000Z"); // a Monday

/* ---------------- fixtures ---------------- */

/** Job sites. The state the work is in decides which Act applies. */
const SITES = [
  { id: "site-parramatta", tag: "JOB-4102", assetClass: "passive", jurisdiction: "NSW" },
  { id: "site-chermside", tag: "JOB-4110", assetClass: "passive", jurisdiction: "QLD" },
  { id: "site-geelong", tag: "JOB-4121", assetClass: "passive", jurisdiction: "VIC" },
];

/** Calendar ceiling for the stub only: the business-day span plus a week, in 30-day months. */
const stubMonths = (businessDays) => (Math.ceil((businessDays * 7) / 5) + 7) / 30;

const rule = (jurisdiction, version, effectiveFrom, businessDays, extra = {}) => ({
  obligationType: "payment-schedule",
  jurisdiction,
  version,
  effectiveFrom,
  businessDays,
  intervalMonths: stubMonths(businessDays),
  retentionYears: 7,
  attestedBy: "nobody: a payment schedule is the business's own document",
  leadDays: 30, // remind from the day the claim lands
  scheduleDraft: "payment schedule to the claimant, scheduled amount and reasons left for a person",
  citation: `the business's own ${jurisdiction} security of payment rule (illustrative)`,
  ...extra,
});

const NSW_CLOSURE = [{ from: "12-27", to: "12-31" }];
const QLD_CLOSURE = [{ from: "12-22", to: "01-10" }];

/** A payment claim on a job, with the site's state mirrored as the register stores it. */
const claim = (id, siteId, extra = {}) => ({
  id,
  assetId: siteId,
  obligationType: "payment-schedule",
  jurisdiction: SITES.find((s) => s.id === siteId).jurisdiction,
  owner: "Dani (contracts administrator)",
  jobId: SITES.find((s) => s.id === siteId).tag,
  ...extra,
});

const world = (rules, obligations, now = NOW) =>
  Object.assign(new CalendarWorld({ now, assets: SITES, rules, obligations }), { marks: [] });

/* ---------------- trace helpers ---------------- */

async function run(build, w, replies) {
  w.marks.push(w.calls.length);
  await build(w.ports(), replies);
}

const callsOf = (w, n) =>
  n === undefined ? w.calls : w.calls.slice(w.marks[n] ?? 0, w.marks[n + 1] ?? w.calls.length);

const raisedCalls = (w, reason, id, n) =>
  callsOf(w, n).filter(
    (c) => c.port === "escalate" && c.request?.reason === reason && String(c.request?.detail ?? "").startsWith(`${id};`),
  );
const raised = (w, reason, id, n) => raisedCalls(w, reason, id, n).length > 0;
/** A reminder that names this due date. */
const remindedFor = (w, reason, id, date, n) =>
  raisedCalls(w, reason, id, n).some((c) => String(c.request.detail).includes(` ${date} `));
const prepared = (w, id, n) => callsOf(w, n).some((c) => c.port === "issue_notice" && c.request?.prepare === id);
const issued = (w, n) => callsOf(w, n).some((c) => c.port === "issue_notice" && c.response?.issued === true);
const dueReads = (w, id, n) => callsOf(w, n).filter((c) => c.port === "read_rule" && c.request?.dueDate === id && c.response);
const versionReads = (w, n) => callsOf(w, n).filter((c) => c.port === "read_rule" && c.request?.obligationType);
const breachedIn = (w, id, n) =>
  callsOf(w, n).filter((c) => c.port === "gate" && c.request?.sweep).at(-1)?.response?.breached?.includes(id) === true;
const completes = (w, id, n) => callsOf(w, n).filter((c) => c.port === "evidence" && c.request?.complete === id);

const describe = (w) =>
  `${w.calls.length} port call(s) over ${w.marks.length} run(s): ` +
  w.calls.map((c) => `${c.port}:${JSON.stringify(c.request)}`).slice(0, 14).join(" | ");

/* ---------------- scenarios ---------------- */

export const scenarios = [
  {
    checkId: "dates-derived-not-stored",
    // A NSW claim served Friday 18 September. Under the first rule version the
    // schedule is due 20 business days later, Friday 16 October. An amendment
    // from 1 October cuts it to 10 business days. On the 1 October run the same
    // claim must re-derive to Friday 2 October, and the reminder must say so.
    // A build that kept the first date carries on telling Dani the 16th.
    world: () =>
      world(
        [
          rule("NSW", "NSW-SOP-OLD", "2019-10-21T00:00:00.000Z", 20),
          rule("NSW", "NSW-SOP-2026-10", "2026-10-01T00:00:00.000Z", 10, { closures: NSW_CLOSURE }),
        ],
        [claim("pc-7731", "site-parramatta", { anchorDate: "2026-09-18T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.advance(10 * DAY);
      await run(build, w);
    },
    holds: (w) => {
      const before = dueReads(w, "pc-7731", 0).at(-1)?.response;
      const after = dueReads(w, "pc-7731", 1).at(-1)?.response;
      return (
        before?.version === "NSW-SOP-OLD" &&
        after?.version === "NSW-SOP-2026-10" &&
        before.date !== after.date &&
        remindedFor(w, "claim.schedule_due", "pc-7731", "2026-10-16", 0) &&
        remindedFor(w, "claim.schedule_due", "pc-7731", "2026-10-02", 1) &&
        !remindedFor(w, "claim.schedule_due", "pc-7731", "2026-10-16", 1)
      );
    },
    describe,
  },
  {
    checkId: "superseded-versions-retained",
    // Two Queensland claims from the same subbie. One fell due last year under
    // the earlier rule version, which must still be readable with its effective
    // date and explain that past due date. The other claims a past due date
    // under a version that was never in the rule set: raised, not explained away.
    world: () =>
      world(
        [
          rule("QLD", "QLD-SOP-2018", "2018-12-17T00:00:00.000Z", 10, { closures: QLD_CLOSURE }),
          rule("QLD", "QLD-SOP-2026", "2026-03-01T00:00:00.000Z", 15, { closures: QLD_CLOSURE }),
        ],
        [
          claim("pc-a", "site-chermside", {
            anchorDate: "2026-09-15T00:00:00.000Z",
            history: [{ date: "2025-06-30T00:00:00.000Z", version: "QLD-SOP-2018" }],
          }),
          claim("pc-b", "site-chermside", {
            anchorDate: "2026-09-15T00:00:00.000Z",
            history: [{ date: "2025-03-14T00:00:00.000Z", version: "QLD-SOP-2004" }],
          }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const read = versionReads(w).find((c) => c.request.jurisdiction === "QLD");
      const old = read?.response?.versions?.find((v) => v.version === "QLD-SOP-2018");
      return (
        typeof old?.effectiveFrom === "string" &&
        dueReads(w, "pc-a").at(-1)?.response?.version === "QLD-SOP-2026" &&
        !raised(w, "claim.history_unexplained", "pc-a") &&
        raised(w, "claim.history_unexplained", "pc-b")
      );
    },
    describe,
  },
  {
    checkId: "rules-per-jurisdiction",
    // Two claims served the same Monday, 14 September: one on the Parramatta
    // job, one on the Chermside job. NSW counts 10 business days, so Monday
    // 28 September. Queensland counts 15, and Monday 5 October is a public
    // holiday in its rule, so Tuesday 6 October. One rule store, read per state.
    world: () =>
      world(
        [
          rule("NSW", "NSW-SOP-2019", "2019-10-21T00:00:00.000Z", 10, { closures: NSW_CLOSURE }),
          rule("QLD", "QLD-SOP-2026", "2026-03-01T00:00:00.000Z", 15, { closures: QLD_CLOSURE, holidays: ["2026-10-05"] }),
        ],
        [
          claim("pc-nsw", "site-parramatta", { anchorDate: "2026-09-14T00:00:00.000Z" }),
          claim("pc-qld", "site-chermside", { anchorDate: "2026-09-14T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const n = dueReads(w, "pc-nsw").at(-1)?.response;
      const q = dueReads(w, "pc-qld").at(-1)?.response;
      const states = new Set(versionReads(w).map((c) => c.request.jurisdiction));
      return (
        n?.version === "NSW-SOP-2019" &&
        q?.version === "QLD-SOP-2026" &&
        n.date !== q.date &&
        states.has("NSW") &&
        states.has("QLD") &&
        remindedFor(w, "claim.schedule_due", "pc-nsw", "2026-09-28", 0) &&
        remindedFor(w, "claim.schedule_due", "pc-qld", "2026-10-06", 0) &&
        !remindedFor(w, "claim.schedule_due", "pc-qld", "2026-09-28", 0)
      );
    },
    describe,
  },
  {
    checkId: "unknown-anchor-surfaces",
    // A claim came in the post to the Geelong site office and was scanned on
    // with no served date. It must surface as unknown and go to Dani; no
    // reminder date and no drafted schedule against a date nobody knows, and
    // never "served today". A second claim with a date is worked as normal.
    world: () =>
      world(
        [rule("VIC", "VIC-SOP-2007", "2007-03-30T00:00:00.000Z", 10)],
        [
          claim("pc-post", "site-geelong"),
          claim("pc-email", "site-geelong", { anchorDate: "2026-09-16T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const marked = (id) => w.calls.some((c) => c.port === "evidence" && c.request?.unknownAnchor === id);
      return (
        marked("pc-post") &&
        raised(w, "claim.served_date_unknown", "pc-post") &&
        !raised(w, "claim.schedule_due", "pc-post") &&
        !raised(w, "claim.schedule_overdue", "pc-post") &&
        !prepared(w, "pc-post") &&
        !marked("pc-email") &&
        dueReads(w, "pc-email").length > 0 &&
        remindedFor(w, "claim.schedule_due", "pc-email", "2026-09-30", 0)
      );
    },
    describe,
  },
  {
    checkId: "evidence-of-completion",
    // Two Done replies, each carrying the claim's obligation id from its link.
    // The overdue Parramatta claim comes back "Done" with nothing attached: not
    // a served schedule, refused, raised, and still overdue. The other carries
    // the served payment schedule: filed and read back, and no reminder goes.
    world: () =>
      world(
        [rule("NSW", "NSW-SOP-2019", "2019-10-21T00:00:00.000Z", 10, { closures: NSW_CLOSURE })],
        [
          claim("pc-late", "site-parramatta", { anchorDate: "2026-08-28T00:00:00.000Z" }),
          claim("pc-ok", "site-parramatta", { anchorDate: "2026-09-16T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w, [
        { kind: "done", obligationId: "pc-late", messageId: "msg-441" },
        { kind: "done", obligationId: "pc-ok", messageId: "msg-442", documentRef: "msg-442/payment-schedule-pc-ok-served.pdf" },
      ]);
    },
    holds: (w) => {
      const tick = completes(w, "pc-late");
      const filed = completes(w, "pc-ok");
      return (
        tick.length > 0 &&
        tick.every((c) => c.response?.accepted === false) &&
        raised(w, "claim.done_without_schedule", "pc-late") &&
        breachedIn(w, "pc-late") &&
        raised(w, "claim.schedule_overdue", "pc-late") &&
        filed.some((c) => c.response?.accepted === true && c.request?.evidenceRef === "msg-442/payment-schedule-pc-ok-served.pdf") &&
        !raised(w, "claim.schedule_due", "pc-ok") &&
        !raised(w, "claim.schedule_overdue", "pc-ok")
      );
    },
    describe,
  },
  {
    checkId: "refusal-is-dated-outcome",
    // The director decides to serve no schedule on a claim and pay it in full.
    // That decision is stored with its date and the claim stays on the
    // calendar. A month later nothing is filed: still live, now breached, and
    // reminded as overdue, because the full claimed amount is now owed.
    world: () =>
      world(
        [rule("NSW", "NSW-SOP-2019", "2019-10-21T00:00:00.000Z", 10, { closures: NSW_CLOSURE })],
        [claim("pc-full", "site-parramatta", { anchorDate: "2026-09-18T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w, [{ kind: "no_schedule", obligationId: "pc-full", by: "the director", at: "2026-09-21T00:00:00.000Z" }]);
      w.advance(30 * DAY);
      await run(build, w);
    },
    holds: (w) => {
      const refusal = callsOf(w, 0).find((c) => c.port === "evidence" && c.request?.refusal === "pc-full");
      return (
        refusal?.request?.at === "2026-09-21T00:00:00.000Z" &&
        raised(w, "claim.no_schedule_decided", "pc-full", 0) &&
        completes(w, "pc-full").length === 0 &&
        breachedIn(w, "pc-full", 1) &&
        raised(w, "claim.schedule_overdue", "pc-full", 1)
      );
    },
    describe,
  },
  {
    checkId: "notice-needs-a-person",
    // A Queensland claim is past its date and the rule names a payment
    // schedule. Nothing is released, so the schedule is drafted and held, and
    // raised for a person. A release that arrives with nobody named is refused.
    // A second overdue claim already has an open exception with Dani, so this
    // run leaves it alone entirely.
    world: () =>
      world(
        [rule("QLD", "QLD-SOP-2026", "2026-03-01T00:00:00.000Z", 15, { closures: QLD_CLOSURE, noticeOnBreach: true })],
        [
          claim("pc-main", "site-chermside", { anchorDate: "2026-08-17T00:00:00.000Z" }),
          claim("pc-held", "site-chermside", {
            anchorDate: "2026-08-17T00:00:00.000Z",
            exceptionOpen: true,
            exceptionOwner: "Dani (contracts administrator)",
          }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
      await run(build, w, [{ kind: "release", obligationId: "pc-main" }]);
    },
    holds: (w) =>
      prepared(w, "pc-main", 0) &&
      raised(w, "claim.schedule_drafted_awaiting_release", "pc-main", 0) &&
      callsOf(w, 1).some((c) => c.port === "issue_notice" && c.request?.release === "pc-main" && c.response?.issued === false) &&
      raised(w, "claim.release_refused", "pc-main", 1) &&
      !issued(w) &&
      !prepared(w, "pc-held") &&
      !raised(w, "claim.schedule_overdue", "pc-held"),
    describe,
  },
  {
    checkId: "breach-does-not-self-clear",
    // A NSW claim's date passed with no schedule served. The first run sees it
    // and reminds. A week later the Done reply arrives with a late-served
    // schedule and is filed. A month on, the register still says it was
    // breached, and no overdue reminder goes: closed, with the history kept.
    world: () =>
      world(
        [rule("NSW", "NSW-SOP-2019", "2019-10-21T00:00:00.000Z", 10, { closures: NSW_CLOSURE })],
        [claim("pc-missed", "site-parramatta", { anchorDate: "2026-08-28T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.advance(7 * DAY);
      await run(build, w, [{ kind: "done", obligationId: "pc-missed", messageId: "msg-501", documentRef: "msg-501/payment-schedule-late.pdf" }]);
      w.advance(30 * DAY);
      await run(build, w);
    },
    holds: (w) =>
      breachedIn(w, "pc-missed", 0) &&
      raised(w, "claim.schedule_overdue", "pc-missed", 0) &&
      completes(w, "pc-missed", 1).some((c) => c.response?.accepted === true) &&
      breachedIn(w, "pc-missed", 2) &&
      !raised(w, "claim.schedule_overdue", "pc-missed", 2),
    describe,
  },
  {
    checkId: "survives-the-builder",
    // A precondition. The runner returns evidence_required before driving it:
    // who else can explain the build, and whose account the claims register
    // runs on, is attested by the business, not by this run.
    world: () => world([], []),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: () => false,
    describe,
  },
];

// Run only in production, which this standard does not offer yet. Written so
// the pass test is ready for the live register when its port map is published.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new CalendarWorld(),
    drive: async (build, w) => {
      w.marks = [];
      await run(build, w);
    },
    holds: (w) =>
      w.calls.some((c) => c.port === "read_rule" && c.request?.dueDate) &&
      w.calls.some((c) => c.port === "gate" && c.request?.sweep) &&
      !issued(w),
    describe,
  },
];
